window.DEX_DATA["sources:backport-549cb99ce2c3ab4e"]={"json":{"skins":[{"filename":"cueball.png"},{"filename":"streetthug.png"}],"names":[{"name":"弹簧刀"},{"name":"古杰"},{"name":"斯塔布斯先生"},{"name":"疯眼"},{"name":"古特莫尔"}],"chat":[{"lines":[{"text":"这是我的地盘，离远点。"},{"text":"没听见我说的话吗？"}]},{"lines":[{"text":"我的同伙随时都会到。"},{"text":"没错，我们可是这片地区最危险的人。"}]},{"lines":[{"text":"我喜欢可爱的宝可梦。曾经有人笑话过我。"},{"text":"就那么一次。我把他吓得够呛，真的。"}]},{"lines":[{"text":"附近有警察的话，记得告诉我。"},{"text":"为什么？因为我对警察和多管闲事的人过敏。"}]}]}};
